/*
 * common.js — shared helpers for tools/build.js and its modules (spec 02 §4).
 *
 * Sources live in content/, output goes to data/. Every generated file starts with the
 * GENERATED header and assigns into window.LM, so it loads with a plain <script> on file://.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const CONTENT = path.join(ROOT, "content");
const DATA = path.join(ROOT, "data");
const LEVELS = ["A1", "A2", "B1", "B2", "C1", "C2"];

function rel(file) { return path.relative(ROOT, file).replace(/\\/g, "/"); }
function exists(file) { return fs.existsSync(file); }
function read(file) { return fs.readFileSync(file, "utf8").replace(/^﻿/, "").replace(/\r\n/g, "\n"); }
function readJson(file) {
  try { return JSON.parse(read(file)); } catch (e) { throw new Error(rel(file) + ": invalid JSON (" + e.message + ")"); }
}
function readJsonIf(file, fallback) { return exists(file) ? readJson(file) : fallback; }
function listFiles(dir, re) {
  if (!exists(dir)) return [];
  return fs.readdirSync(dir).filter(function (f) { return re.test(f) && fs.statSync(path.join(dir, f)).isFile(); }).sort();
}
function listDirs(dir) {
  if (!exists(dir)) return [];
  return fs.readdirSync(dir).filter(function (f) { return fs.statSync(path.join(dir, f)).isDirectory(); }).sort();
}

/** Front matter: values are plain text after the FIRST colon (spec 07 §1). */
function splitMd(md) {
  const m = /^---\n([\s\S]*?)\n---\n?/.exec(md);
  const meta = {};
  if (m) m[1].split("\n").forEach(function (line) {
    const k = /^([A-Za-z][\w-]*):\s*(.*)$/.exec(line);
    if (k) meta[k[1]] = k[2].replace(/\s+#.*$/, "").trim();
  });
  return { meta: meta, body: m ? md.slice(m[0].length) : md };
}

const written = [];

/**
 * Writes data/<relOut> as `/* GENERATED … *\/ window.LM = …; <body>`.
 * sources: short description of the content/… files it comes from.
 */
function writeData(relOut, sources, body) {
  const file = path.join(module.exports.OUT || DATA, relOut);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const text = "/* GENERATED by tools/build.js — do not edit. Source: " + sources + " */\n" +
    "window.LM = window.LM || {};\n" + body.trim() + "\n";
  fs.writeFileSync(file, text, "utf8");
  written.push("data/" + relOut);
  return file;
}

/** LM.<NAME> = value; */
function assign(name, value) { return "LM." + name + " = " + JSON.stringify(value) + ";"; }
/** (LM.<NAME> = LM.<NAME> || {})[key] = value; */
function assignKey(name, key, value) {
  return "(LM." + name + " = LM." + name + " || {})[" + JSON.stringify(key) + "] = " + JSON.stringify(value) + ";";
}

/** Topic id "a1-verbs-gustar" → page file "a1/verbs-gustar.md" (spec 02 §2). */
function pageFileOf(topicId) {
  const m = /^([abc][12])-(.+)$/.exec(topicId);
  return m ? m[1] + "/" + m[2] + ".md" : null;
}

module.exports = {
  ROOT: ROOT, CONTENT: CONTENT, DATA: DATA, LEVELS: LEVELS,
  path: path, fs: fs, rel: rel, exists: exists, read: read, readJson: readJson, readJsonIf: readJsonIf,
  listFiles: listFiles, listDirs: listDirs, splitMd: splitMd,
  writeData: writeData, assign: assign, assignKey: assignKey, written: written, pageFileOf: pageFileOf
};
